/**
 * Radicals screen — `#/learn/radicals` (list of 214 Kangxi radicals with search)
 * and `#/learn/radicals/<hanzi>` (character decomposition view).
 *
 * Data from `public/data/radicals/` (generated by scripts/build-radicals.mjs):
 *   - radicals.json: 214 Kangxi radicals {number, symbol, pinyin, meaning, strokes}
 *   - decomposition-index.json + shards: {parts:[], radical, kangxiNumber} per character
 *   - reverse-index.json + shards: component -> [characters containing it]
 *
 * Screen contract: `titleKey` + `render(container, ctx)` (returns cleanup fn).
 *
 * Public API (browser-free helpers, covered by tests/radicals.test.mjs):
 *   getDecomposition(char)            -> { parts, radical, kangxiNumber } | null
 *   loadRadicalIndex()                -> radicals.json array (cached)
 *   loadDecompositionIndex()          -> decomposition-index.json
 *   loadReverseIndex()                -> reverse-index.json
 *   searchRadicals(query, index, opts) -> radical[]  (by symbol, pinyin, meaning)
 *   createRadicalLoader({base})       -> { loadIndex, loadDecomposition, loadReverse, searchRadicals }
 *
 * Wiring with the app (only these imports):
 *   - review: addToReview({hanzi, pinyin, english, source: 'radicals'}) (src/srs.js)
 *   - audio:  speak(character, {lang: 'zh-CN'}) (src/audio.js), never throws
 *   - i18n:   t(key), pinyinHtml(pinyin) (src/tone.js)
 *   - window event `chino:lesson_done` fired when user adds a character from a radical
 */
import { t } from '../i18n.js';
import { h, reset } from '../dom.js';
import { speak } from '../audio.js';
import { addToReview } from '../srs.js';
import { pinyinHtml } from '../tone.js';
import { search as dictSearch, lookup as dictLookup } from '../dictionary.js';
import { tonelessKey } from '../pinyin.js';

export const titleKey = 'radicals.title';

/** Where the browser build serves the radical shards from (next to `src/`). */
export const DEFAULT_RADICAL_BASE = new URL('../../data/radicals/', import.meta.url);

let fetcher = null;
let defaultLoader = null;

/** Inject a fetch implementation (Node tests, workers). Clears the cache. */
export function configure(opts = {}) {
  if (typeof opts.fetch === 'function') {
    fetcher = opts.fetch;
  }
  defaultLoader = null; // Will be recreated on next use
}

function getDefaultLoader() {
  if (!defaultLoader) {
    defaultLoader = createRadicalLoader();
  }
  return defaultLoader;
}

