function ensureStyles(doc) {
  if (doc.getElementById('radicals-style')) return;
  const style = doc.createElement('style');
  style.id = 'radicals-style';
  style.textContent = CSS;
  doc.head.append(style);
}

/** Normalize a route segment to a single CJK character (simplified). */
export function normalizeCharacter(value) {
  if (value === undefined || value === null) return '';
  let text = String(value).trim();
  if (!text) return '';
  try { text = decodeURIComponent(text); } catch { /* malformed */ }
  const match = text.match(/[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/u);
  return match ? match[0] : '';
}

/** Normalize pinyin for search: strip tone marks/numbers, lowercase. */
export function normalizePinyinForSearch(pinyin) {
  return tonelessKey(pinyin || '').toLowerCase();
}

/** Search radicals by symbol, pinyin, or meaning. */
export function searchRadicals(query, radicals, { limit = 20 } = {}) {
  const q = String(query ?? '').trim().toLowerCase();
  const qNorm = normalizePinyinForSearch(q);
  if (!q && !qNorm) return [];
  if (!Array.isArray(radicals)) return [];
  const out = [];
  for (const r of radicals) {
    const symbol = r.symbol || '';
    const pinyin = normalizePinyinForSearch(r.pinyin);
    const meaning = (r.meaning || '').toLowerCase();
    const symbolMatch = symbol.includes(q);
    const pinyinMatch = qNorm && pinyin.includes(qNorm);
    const meaningMatch = meaning.includes(q);
    if (symbolMatch || pinyinMatch || meaningMatch) {
      out.push(r);
      if (out.length >= limit) break;
    }
  }
  return out;
}

/** Loader for `public/data/radicals/` (index + shards). */
export function createRadicalLoader({ base = DEFAULT_RADICAL_BASE, fetchImpl } = {}) {
  const root = toBaseUrl(base);
  const cache = new Map();

  const fetchJson = async (url) => {
    if (cache.has(url)) return cache.get(url);
    const pending = (async () => {
      if (fetchImpl) return fetchImpl(url);
      if (fetcher) return fetcher(url);
      const response = await fetch(url);
      if (!response.ok) throw new Error(`radicals: HTTP ${response.status} for ${url}`);
      return response.json();
    })();
    cache.set(url, pending);
    try { return await pending; }
    catch (error) { cache.delete(url); throw error; }
  };

  const loadRadicalIndex = () => fetchJson(new URL('radicals.json', root).href);

  const loadDecompositionIndex = () => fetchJson(new URL('decomposition-index.json', root).href);

  const loadReverseIndex = () => fetchJson(new URL('reverse-index.json', root).href);

  /** Find shard index for a character using the shard ranges (binary search). */
  function findShardIndex(index, char) {
    const shards = index.shards;
    if (!shards || !shards.length) return -1;
    const code = char.codePointAt(0);
    let lo = 0, hi = shards.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const range = shards[mid].range;
      if (!range || range.length < 2) { lo = mid + 1; continue; }
      const start = range[0].codePointAt(0);
      const end = range[1].codePointAt(0);
      if (code < start) hi = mid - 1;
      else if (code > end) lo = mid + 1;
      else return mid;
    }
    return -1;
  }

  const loadDecomposition = async (character) => {
    const char = normalizeCharacter(character);
    if (!char) return null;
    const index = await loadDecompositionIndex();
    const shardIdx = findShardIndex(index, char);
    if (shardIdx < 0) return null;
    const file = index.shardFiles?.[shardIdx] ?? `shards/${String(shardIdx).padStart(3, '0')}.json`;
    const shard = await fetchJson(new URL(file, root).href);
    return shard[char] ?? null;
  };

  const loadReverse = async (component) => {
    const comp = normalizeCharacter(component);
    if (!comp) return null;
    const index = await loadReverseIndex();
    const shardIdx = findShardIndex(index, comp);
    if (shardIdx < 0) return null;
    const file = index.shardFiles?.[shardIdx] ?? `reverse-shards/${String(shardIdx).padStart(3, '0')}.json`;
    const shard = await fetchJson(new URL(file, root).href);
    return shard[comp] ?? null;
  };

  const search = async (query, options) => {
    const radicals = await loadRadicalIndex();
    return searchRadicals(query, radicals, options);
  };

  return { loadRadicalIndex, loadDecompositionIndex, loadReverseIndex, loadDecomposition, loadReverse, search };
}

/** All 214 Kangxi radicals (cached after first load). */
export const loadRadicalIndex = () => getDefaultLoader().loadRadicalIndex();

/** Decomposition entry for one character: {parts, radical, kangxiNumber} or null. */
export const getDecomposition = (character) => getDefaultLoader().loadDecomposition(character);

/** Characters containing a component (from reverse index) or null. */
export const loadReverse = (component) => getDefaultLoader().loadReverse(component);

/** Search radicals by query (symbol/pinyin/meaning). */
export const searchRadicalsAsync = (query, options) => getDefaultLoader().search(query, options);

function toBaseUrl(base) {
  if (base instanceof URL) return base;
  const text = String(base ?? DEFAULT_RADICAL_BASE.href);
  try { return new URL(text); }
  catch { return new URL(text.endsWith('/') ? text : `${text}/`, DEFAULT_RADICAL_BASE); }
}

/* ------------------------------------------------------------------ *
 * Screen: radical list + decomposition view
 * ------------------------------------------------------------------ */

const SEARCH_DEBOUNCE_MS = 150;

export async function render(container, ctx = {}) {
  ensureStyles(document);

  const segments = ctx?.route?.segments ?? [];
  const area = segments[0]; // 'radicals'
  const charParam = segments[1]; // character for decomposition view

  // If a character is provided, show decomposition view
  if (charParam) {
    return renderDecomposition(container, ctx, charParam);
  }

  // Otherwise show the radical list with search
  return renderRadicalList(container, ctx);
}

/** Radical list screen: search + grid of 214 radicals. */
async function renderRadicalList(container, ctx) {
  const state = { seq: 0, timer: null, alive: true, radicals: null };

  const input = h('input', {
    type: 'search',
    class: 'radicals-input',
    name: 'q',
    autocomplete: 'off',
    'aria-label': t('radicals.searchLabel'),
    placeholder: t('radicals.searchPlaceholder'),
  });
  const list = h('div', { class: 'radicals-list', 'aria-label': t('radicals.searchResults') });
  const empty = h('p', { class: 'radicals-empty', hidden: true });
  const error = h('p', { class: 'radicals-error', hidden: true });
  const loading = h('p', { class: 'radicals-loading', hidden: true, text: t('radicals.loading') });

  const form = h('form', { class: 'radicals-search', onsubmit: onSubmit }, input,
    h('button', { type: 'submit', class: 'radicals-go', text: t('radicals.searchButton') || 'Search' }));

  const section = h('section', { class: 'radicals' }, form, loading, list, empty, error);
  reset(container).append(section);
  container.focus({ preventScroll: true });

  async function loadRadicals() {
    if (state.radicals) return state.radicals;
    try {
      state.radicals = await loadRadicalIndex();
      return state.radicals;
    } catch (err) {
      console.error('radicals: failed to load index', err);
      throw err;
    }
  }

  function setLoading(on) {
    loading.hidden = !on;
    list.hidden = on;
    empty.hidden = true;
    error.hidden = true;
  }

  function setError(msgKey) {
    loading.hidden = true;
    list.hidden = true;
    empty.hidden = true;
    error.hidden = false;
    error.textContent = t(msgKey);
  }

  function setEmpty() {
    loading.hidden = true;
    list.hidden = true;
    empty.hidden = false;
    error.hidden = true;
    empty.textContent = t('radicals.noRadicals');
  }

  function renderList(radicals) {
    list.replaceChildren();
    if (!radicals.length) { setEmpty(); return; }
    loading.hidden = true;
    list.hidden = false;
    empty.hidden = true;
    error.hidden = true;
    for (const r of radicals) {
      const btn = h('button', {
        type: 'button',
        class: 'radical-btn',
        'data-radical': r.symbol,
        'data-number': r.number,
        onclick: () => ctx.navigate?.(`learn/radicals/${encodeURIComponent(r.symbol)}`),
      },
        h('span', { class: 'radical-symbol', text: r.symbol }),
        h('div', { class: 'radical-info' },
          h('span', { text: r.pinyin }),
          h('span', { text: r.meaning }),
        )
      );
      list.append(btn);
    }
  }

  async function runSearch(query) {
    const seq = ++state.seq;
    setLoading(true);
    try {
      const radicals = await loadRadicals();
      if (seq !== state.seq || !state.alive) return;
      const results = searchRadicals(query, radicals, { limit: 214 });
      if (seq !== state.seq || !state.alive) return;
      renderList(results);
    } catch (err) {
      if (seq !== state.seq || !state.alive) return;
      console.error('radicals: search failed', err);
      setError('radicals.loadError');
    }
  }

  function onSubmit(event) {
    event.preventDefault();
    clearTimeout(state.timer);
    runSearch(input.value.trim());
  }

  input.addEventListener('input', () => {
    clearTimeout(state.timer);
    const query = input.value.trim();
    if (!query) {
      loadRadicals().then(radicals => {
        if (!state.alive) return;
        renderList(radicals);
      }).catch(() => { if (state.alive) setError('radicals.loadError'); });
      return;
    }
    state.timer = setTimeout(() => runSearch(query), SEARCH_DEBOUNCE_MS);
  });

  // Initial load: show all radicals
  loadRadicals()
    .then(radicals => { if (state.alive) renderList(radicals); })
    .catch(() => { if (state.alive) setError('radicals.loadError'); });

  return () => { state.alive = false; clearTimeout(state.timer); };
}

/** Decomposition screen for a single character. */
async function renderDecomposition(container, ctx, charParam) {
  const character = normalizeCharacter(charParam);
  if (!character) {
    reset(container).append(h('p', { class: 'radicals-error', text: t('radicals.noDecomposition') }));
    return () => {};
  }

  const state = { alive: true, decomp: null, reverseChars: null, dictEntries: new Map() };

  const header = h('div', { class: 'decomp-header' });
  const partsRow = h('div', { class: 'decomp-parts' });
  const charsGrid = h('div', { class: 'decomp-chars' });
  const empty = h('p', { class: 'radicals-empty', hidden: true });
  const error = h('p', { class: 'radicals-error', hidden: true });
  const loading = h('p', { class: 'radicals-loading', hidden: true, text: t('radicals.loading') });
  const actions = h('div', { class: 'decomp-actions' });

  const speakBtn = h('button', { type: 'button', text: t('radicals.speak'), onclick: onSpeak });
  const reviewBtn = h('button', { type: 'button', text: t('radicals.addToReview'), onclick: onAddToReview });
  actions.append(speakBtn, reviewBtn);

  const section = h('section', { class: 'radicals-decomp' }, header, partsRow, loading, charsGrid, empty, error, actions);
  reset(container).append(section);
  container.focus({ preventScroll: true });

  async function load() {
    try {
      loading.hidden = false;
      charsGrid.hidden = true;
      partsRow.hidden = true;
      empty.hidden = true;
      error.hidden = true;

      const [decomp, reverseChars] = await Promise.all([
        getDecomposition(character),
        loadReverse(character),
      ]);

      if (!state.alive) return;
      state.decomp = decomp;
      state.reverseChars = reverseChars || [];

      renderHeader();
      renderParts();
      await loadDictionaryEntries();
      renderChars();
    } catch (err) {
      console.error('radicals: decomposition load failed', err);
      if (state.alive) {
        loading.hidden = true;
        error.hidden = false;
        error.textContent = t('radicals.loadError');
      }
    }
  }

  function renderHeader() {
    header.replaceChildren();
    const radicalInfo = state.decomp?.radical ? `${state.decomp.radical} (Kangxi #${state.decomp.kangxiNumber ?? '—'})` : '—';
    header.append(
      h('span', { class: 'decomp-char', text: character }),
      h('span', { class: 'decomp-radical', text: t('radicals.radical', { radical: radicalInfo }) || `Radical: ${radicalInfo}` })
    );
  }

  function renderParts() {
    partsRow.replaceChildren();
    const parts = state.decomp?.parts ?? [];
    if (!parts.length) {
      partsRow.hidden = true;
      return;
    }
    partsRow.hidden = false;
    for (const part of parts) {
      const btn = h('button', {
        type: 'button',
        class: 'decomp-part',
        text: part,
        onclick: () => ctx.navigate?.(`learn/radicals/${encodeURIComponent(part)}`),
      });
      partsRow.append(btn);
    }
  }

  async function loadDictionaryEntries() {
    // Load dictionary entries for all characters in reverse index (for pinyin/meaning)
    // Limit to first 50 to avoid too many requests
    const chars = state.reverseChars.slice(0, 50);
    for (const ch of chars) {
      if (!state.alive) break;
      try {
        const entry = await dictLookup(ch);
        if (entry) state.dictEntries.set(ch, entry);
      } catch { /* ignore */ }
    }
  }

  function renderChars() {
    if (!state.alive) return;
    loading.hidden = true;
    const chars = state.reverseChars;
    if (!chars.length) {
      empty.hidden = false;
      empty.textContent = t('radicals.noDecomposition');
      charsGrid.hidden = true;
      return;
    }
    charsGrid.hidden = false;
    charsGrid.replaceChildren();
    for (const ch of chars) {
      const entry = state.dictEntries.get(ch);
      const pinyin = entry?.pinyinTone || entry?.pinyinNum || '';
      const meaning = entry?.defs?.[0] || entry?.defs?.[1] || '';
      const btn = h('button', {
        type: 'button',
        class: 'decomp-char-btn',
        'data-char': ch,
        onclick: () => ctx.navigate?.(`learn/radicals/${encodeURIComponent(ch)}`),
      },
        h('span', { class: 'char-hanzi', text: ch }),
        h('span', { class: 'char-pinyin', html: pinyinHtml(pinyin) }),
        h('span', { class: 'char-meaning', text: meaning }),
      );
      charsGrid.append(btn);
    }
  }

  async function onSpeak() {
    const result = await speak(character, { lang: 'zh-CN' });
    if (!result?.ok && result?.reason !== 'empty') {
      const msg = result?.reason === 'unsupported' ? 'radicals.speakUnsupported' : 'radicals.speakError';
      alert(t(msg)); // Simple notification; could be improved with toast
    }
  }

  async function onAddToReview() {
    const entry = state.dictEntries.get(character);
    const pinyin = entry?.pinyinTone || entry?.pinyinNum || '';
    const defs = entry?.defs || [];
    try {
      await addToReview({ hanzi: character, pinyin, english: defs, source: 'radicals' });
      reviewBtn.textContent = t('radicals.addedToReview');
      reviewBtn.disabled = true;
    } catch (err) {
      console.error('radicals: add to review failed', err);
      alert(t('radicals.reviewError'));
    }
  }

  load();
  return () => { state.alive = false; };
}